select set_config('request.jwt.claims','{"sub":"15200000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1","active_tenant_id":"15200000-0000-4000-8000-000000000002","active_membership_id":"15200000-0000-4000-8000-000000000004","active_context_id":"15200000-0000-4000-8000-000000000005"}',true);
set local role authenticated;
select throws_ok($$select customer_api.list_work_orders_v1('15200000-0000-4000-8000-000000000005')$$,'42501','mfa_required','Work-order read retains mandatory AAL2');
reset role;
select set_config('request.jwt.claims','{}',true);
set local role authenticated;
select throws_ok($$select customer_api.list_work_orders_v1('15200000-0000-4000-8000-000000000005')$$,'42501','authentication_required','Unauthenticated read denied: list_work_orders_v1');
select throws_ok($$select customer_api.list_maintenance_requests_v1('15200000-0000-4000-8000-000000000005')$$,'42501','authentication_required','Unauthenticated read denied: list_maintenance_requests_v1');
select throws_ok($$select customer_api.get_maintenance_summary_v1('15200000-0000-4000-8000-000000000005')$$,'42501','authentication_required','Unauthenticated read denied: get_maintenance_summary_v1');
reset role;
select is((select count(*) from maintenance.vendor_payables where tenant_id='15200000-0000-4000-8000-000000000002'),4::bigint,'Reads create no payable');
select is((select count(*) from finance.journals where tenant_id='15200000-0000-4000-8000-000000000002'),4::bigint,'Reads create no journal');
select is((select count(*) from audit.events where tenant_id='15200000-0000-4000-8000-000000000002' and action like 'maintenance.%'),0::bigint,'Read routes emit no maintenance mutation audit');
select ok(not (select prosecdef from pg_proc where oid='customer_api.list_maintenance_requests_v1(uuid,text,integer,integer)'::regprocedure),'list_maintenance_requests_v1 remains SECURITY INVOKER');
select ok(not (select prosecdef from pg_proc where oid='customer_api.list_work_orders_v1(uuid,text,integer,integer)'::regprocedure),'list_work_orders_v1 remains SECURITY INVOKER');
select ok(not (select prosecdef from pg_proc where oid='customer_api.get_maintenance_summary_v1(uuid)'::regprocedure),'get_maintenance_summary_v1 remains SECURITY INVOKER');
select ok(not has_table_privilege('authenticated','maintenance.tickets','select'),'Authenticated direct tickets access stays closed');
select ok(not has_table_privilege('authenticated','maintenance.work_orders','select'),'Authenticated direct work_orders access stays closed');
select ok(not has_table_privilege('authenticated','maintenance.vendors','select'),'Authenticated direct vendors access stays closed');
select ok(not (select rolbypassrls or rolcanlogin or rolsuper from pg_roles where rolname='cladora_rpc_owner'),'Reader role cannot log in or bypass RLS');
select is((select r.rolname::text from pg_proc p join pg_roles r on r.oid=p.proowner where p.oid='maintenance.read_scoped_maintenance_v1(uuid,text,text,integer,integer)'::regprocedure),'cladora_rpc_owner','Read model uses least-privileged existing role');
select ok(not pg_has_role('authenticated','cladora_rpc_owner','member'),'Authenticated cannot assume reader role');
select ok(not has_schema_privilege('cladora_rpc_owner','maintenance','create'),'Reader role cannot create functions or tables');
select ok(not has_table_privilege('cladora_rpc_owner','auth.users','select'),'Reader role cannot read Auth users');
select set_config('request.jwt.claims','{"sub":"15200000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select set_config('cladora.maintenance_read_context_id','previous-scope-sentinel',true);
set local role authenticated;
select is(jsonb_array_length(customer_api.list_work_orders_v1('15200000-0000-4000-8000-000000000044')),1,'Standard JWT without active-scope claims works: list_work_orders_v1');
select is(jsonb_array_length(customer_api.list_maintenance_requests_v1('15200000-0000-4000-8000-000000000044')),1,'Standard JWT without active-scope claims works: list_maintenance_requests_v1');
select is((customer_api.get_maintenance_summary_v1('15200000-0000-4000-8000-000000000044')->>'total_payables_amount')::numeric,20::numeric,'Standard JWT reads only explicit unit financial amount');
select is(current_setting('cladora.maintenance_read_context_id',true),'previous-scope-sentinel','Successful read restores prior transaction scope');
select throws_ok($$select maintenance.read_scoped_maintenance_v1('15200000-0000-4000-8000-000000000044','financial_write')$$,'22023','invalid_query','Read model view allowlist excludes financial writes');
select is(current_setting('cladora.maintenance_read_context_id',true),'previous-scope-sentinel','Failed read restores prior transaction scope');
reset role;
select * from finish();
rollback;
